import {createRenderer} from './render.js';
import {selectionBounds} from './selection.js';
import {layerState} from './folders.js';
import {filterPadding} from './filters.js';
import {withPNGResolution,withJPEGResolution,rasterPDF} from './export-formats.js';
export const exportLimits=Object.freeze({dimension:8192,pixels:16*1024*1024,tile:512,file:48*1024*1024,regions:16,catalog:256*1024,boards:64});
export function exportRect(r){if(!r||![r.minX,r.minY,r.width,r.height].every(Number.isFinite)||Math.abs(r.minX)>1e7||Math.abs(r.minY)>1e7||r.width<=0||r.height<=0||r.width>2e7||r.height>2e7||Math.abs(r.minX+r.width)>1e7||Math.abs(r.minY+r.height)>1e7)throw Error('Enter a valid finite export rectangle');return{minX:r.minX,minY:r.minY,width:r.width,height:r.height};}
export function outputSize({unit='px',width,height,dpi=300}){if(!['px','in'].includes(unit)||![width,height,dpi].every(Number.isFinite)||width<=0||height<=0||!Number.isInteger(dpi)||dpi<36||dpi>1200)throw Error('Enter positive dimensions and a whole-number DPI from 36 to 1200');const w=Math.round(width*(unit==='in'?dpi:1)),h=Math.round(height*(unit==='in'?dpi:1));if(w<1||h<1||w>exportLimits.dimension||h>exportLimits.dimension||w*h>exportLimits.pixels)throw Error('Output exceeds 8192 pixels per side or 16 megapixels · reduce dimensions');return{width:w,height:h,dpi};}
export function exportView(rect,width,height,fit='fit'){const r=exportRect(rect);if(!['fit','crop'].includes(fit))throw Error('Invalid framing mode');const scale=(fit==='fit'?Math.min:Math.max)(width/r.width,height/r.height);return{x:(width-r.width*scale)/2-r.minX*scale,y:(height-r.height*scale)/2-r.minY*scale,scale};}
export function artworkBounds(board){let box=null;for(const l of board.layers){if(!layerState(board,l).visible||!l.opacity)continue;const ids=l.strokes.filter(s=>s.opacity!==0).map(s=>s.id);if(!ids.length)continue;const b=selectionBounds(board,ids,{layerIds:[l.id]});if(!box)box={minX:b.minX,minY:b.minY,width:b.width,height:b.height};else{const x=Math.min(box.minX,b.minX),y=Math.min(box.minY,b.minY);box={minX:x,minY:y,width:Math.max(box.minX+box.width,b.maxX)-x,height:Math.max(box.minY+box.height,b.maxY)-y};}}if(!box)throw Error('No visible artwork · use current view or enter a frame');const p=filterPadding(board)+8;return exportRect({minX:box.minX-p,minY:box.minY-p,width:box.width+2*p,height:box.height+2*p});}
export function validateRegions(list){if(!Array.isArray(list)||list.length>exportLimits.regions)throw Error('Up to 16 saved regions per board');const ids=new Set(),names=new Set();return list.map(r=>{if(!r||typeof r.id!=='string'||!r.id||r.id.length>128||typeof r.name!=='string'||!r.name.trim()||r.name.length>64||ids.has(r.id)||names.has(r.name.trim().toLowerCase())||Object.keys(r).sort().join(',')!=='height,id,minX,minY,name,width')throw Error('Invalid or duplicate named region');ids.add(r.id);names.add(r.name.trim().toLowerCase());return{id:r.id,name:r.name.trim(),...exportRect(r)};});}
export function importRegions(current,input,makeId=()=>crypto.randomUUID()){validateRegions(current);if(!input||input.version!==1||Object.keys(input).sort().join(',')!=='regions,version')throw Error('Invalid region backup');const added=validateRegions(input.regions),out=structuredClone(current);for(const r of added){let name=r.name,n=2;while(out.some(x=>x.name.toLowerCase()===name.toLowerCase()))name=r.name.slice(0,55)+' ('+n+++')';out.push({...r,id:makeId(),name});}return validateRegions(out);}
export function regionCatalog(text){if(typeof text!=='string'||text.length>exportLimits.catalog)throw Error('Region storage limit reached');const c=JSON.parse(text);if(!c||c.version!==1||!Array.isArray(c.entries)||c.entries.length>exportLimits.boards||Object.keys(c).sort().join(',')!=='entries,version')throw Error('Invalid region storage');const ids=new Set();for(const e of c.entries){if(!e||typeof e.boardId!=='string'||!e.boardId||e.boardId.length>128||ids.has(e.boardId)||Object.keys(e).sort().join(',')!=='boardId,regions')throw Error('Invalid region storage');ids.add(e.boardId);validateRegions(e.regions);}return c;}
const task=()=>new Promise(r=>setTimeout(r,0));
const check=s=>{if(s?.aborted)throw new DOMException('Artwork export cancelled','AbortError');};
const encode=(canvas,type,quality)=>new Promise((yes,no)=>canvas.toBlob(b=>b&&b.type===type?yes(b):no(Error('This browser cannot encode the requested image format')),type,quality));
export async function exportArtwork(board,options,{signal,onProgress=()=>{}}={}){
 const size=outputSize(options),rect=exportRect(options.rect),v=exportView(rect,size.width,size.height,options.fit||'fit'),format=options.format||'png',background=options.background||'paper';
 if(!['png','jpg','pdf'].includes(format)||!['paper','white','transparent'].includes(background)||background==='transparent'&&format!=='png')throw Error('Transparency is available for PNG only');
 check(signal);await document.fonts.ready;check(signal);const output=document.createElement('canvas'),tile=document.createElement('canvas');output.width=size.width;output.height=size.height;const ctx=output.getContext('2d'),ratio=1/(window.devicePixelRatio||1);let tileW=1,tileH=1;
 tile.getBoundingClientRect=()=>({width:tileW*ratio,height:tileH*ratio});const renderer=createRenderer(tile,{backend:'canvas2d',layerCacheBytes:0,groupCacheBytes:0});
 // Paper override is a disposable render projection, never a native document.
 const scene=background==='paper'?board:{...board,paper:{...board.paper,kind:'plain',color:background==='white'?'#ffffff':'#00000000'}};
 const pad=background==='transparent'?null:background==='white'?'#ffffff':board.paper.color;
 try{
  const total=Math.ceil(size.width/exportLimits.tile)*Math.ceil(size.height/exportLimits.tile);let done=0;
  for(let y=0;y<size.height;y+=exportLimits.tile)for(let x=0;x<size.width;x+=exportLimits.tile){check(signal);tileW=Math.min(exportLimits.tile,size.width-x);tileH=Math.min(exportLimits.tile,size.height-y);
   renderer.renderReference(scene,{x:(v.x-x)*ratio,y:(v.y-y)*ratio,scale:v.scale*ratio});if(tile.width!==tileW||tile.height!==tileH)throw Error('Effects exceed the requested export resolution · reduce dimensions');
   if(pad){ctx.fillStyle=pad;ctx.fillRect(x,y,tileW,tileH);}ctx.save();ctx.beginPath();ctx.rect(rect.minX*v.scale+v.x,rect.minY*v.scale+v.y,rect.width*v.scale,rect.height*v.scale);ctx.clip();ctx.drawImage(tile,x,y);ctx.restore();onProgress({done:++done,total});await task();
  }
  check(signal);const raw=await encode(output,format==='png'?'image/png':'image/jpeg',.95);check(signal);if(raw.size>exportLimits.file)throw Error('Encoded image exceeds 48 MiB');const bytes=new Uint8Array(await raw.arrayBuffer());const blob=format==='png'?withPNGResolution(bytes,size.dpi):format==='jpg'?withJPEGResolution(bytes,size.dpi):rasterPDF(bytes,size.width,size.height,size.dpi);if(blob.size>exportLimits.file)throw Error('Export file exceeds 48 MiB');check(signal);return{blob,format,...size};
 }finally{for(const c of new Set([output,...renderer.surfaces]))c.width=c.height=1;renderer.invalidate('export-release');}
}
